#!/usr/bin/env python3
"""Parse a truncated SQLite database file and recover all rows."""

import struct
import json

def parse_varint(data, offset):
    """Parse a SQLite varint at the given offset."""
    result = 0
    i = 0
    while True:
        byte = data[offset + i]
        result = (result << 7) | (byte & 0x7F)
        i += 1
        if not (byte & 0x80):
            break
    return result, i

def parse_serial_type(serial_type):
    """Return (data_type, byte_count) for a SQLite serial type code."""
    if serial_type == 0:
        return ('NULL', 0)
    elif serial_type == 1:
        return ('INT8', 1)
    elif serial_type == 2:
        return ('INT16', 2)
    elif serial_type == 3:
        return ('INT24', 3)
    elif serial_type == 4:
        return ('INT32', 4)
    elif serial_type == 5:
        return ('INT48', 6)
    elif serial_type == 6:
        return ('INT64', 8)
    elif serial_type == 7:
        return ('FLOAT64', 8)
    elif serial_type == 8:
        return ('ZERO', 0)  # integer 0
    elif serial_type == 9:
        return ('ONE', 0)   # integer 1
    elif serial_type >= 12:
        if serial_type % 2 == 0:
            # BLOB: (serial_type - 12) / 2 bytes
            return ('BLOB', (serial_type - 12) // 2)
        else:
            # TEXT: (serial_type - 13) / 2 bytes
            return ('TEXT', (serial_type - 13) // 2)
    return ('UNKNOWN', 0)

def decode_value(data, offset, serial_type_code):
    """Decode a value based on its serial type code."""
    type_name, byte_count = parse_serial_type(serial_type_code)

    if type_name == 'NULL':
        return None, 0
    elif type_name == 'ZERO':
        return 0, 0
    elif type_name == 'ONE':
        return 1, 0
    elif type_name == 'INT8':
        val = data[offset]
        if val > 127:
            val -= 256
        return val, 1
    elif type_name == 'INT16':
        val = struct.unpack_from('>h', data, offset)[0]
        return val, 2
    elif type_name == 'INT24':
        val = data[offset] << 16 | data[offset+1] << 8 | data[offset+2]
        if val > 0x7FFFFF:
            val -= 0x1000000
        return val, 3
    elif type_name == 'INT32':
        val = struct.unpack_from('>i', data, offset)[0]
        return val, 4
    elif type_name == 'INT48':
        val = data[offset] << 40 | data[offset+1] << 32 | data[offset+2] << 24 | data[offset+3] << 16 | data[offset+4] << 8 | data[offset+5]
        if val > 0x7FFFFFFFFFFF:
            val -= 0x1000000000000
        return val, 6
    elif type_name == 'INT64':
        val = struct.unpack_from('>q', data, offset)[0]
        return val, 8
    elif type_name == 'FLOAT64':
        val = struct.unpack_from('>d', data, offset)[0]
        # If it's a round number, return as int for cleaner output
        if val == int(val):
            return int(val), 8
        return val, 8
    elif type_name == 'TEXT':
        val = data[offset:offset+byte_count].decode('ascii', errors='replace')
        return val, byte_count
    elif type_name == 'BLOB':
        val = data[offset:offset+byte_count].hex()
        return val, byte_count
    else:
        return None, 0

def parse_page(data):
    """Parse a SQLite b-tree leaf table page."""
    if len(data) < 8:
        return []

    page_type = data[0]
    if page_type != 0x0D:  # leaf table page
        print(f"Unexpected page type: {page_type:#04x}, expected 0x0D (leaf table)")
        return []

    first_freeblock = struct.unpack_from('>H', data, 1)[0]
    num_cells = struct.unpack_from('>H', data, 3)[0]
    content_start = struct.unpack_from('>H', data, 5)[0]
    fragmented_free = data[7]

    print(f"Page type: leaf table")
    print(f"Number of cells: {num_cells}")
    print(f"Content area starts at: {content_start:#06x}")
    print(f"Fragmented free bytes: {fragmented_free}")
    print()

    # Read cell pointers (2 bytes each, starting at offset 8)
    rows = []
    cell_pointers = []
    for i in range(num_cells):
        ptr = struct.unpack_from('>H', data, 8 + i * 2)[0]
        cell_pointers.append(ptr)

    print(f"Cell pointers: {[f'{p:#06x}' for p in cell_pointers]}")
    print()

    for i, cell_offset in enumerate(cell_pointers):
        try:
            print(f"--- Cell {i} at offset {cell_offset:#06x} ---")

            # Parse payload length varint
            payload_length, varint_len = parse_varint(data, cell_offset)
            print(f"  Payload length: {payload_length}")
            offset = cell_offset + varint_len

            # Parse row ID varint
            row_id, varint_len2 = parse_varint(data, offset)
            print(f"  Row ID: {row_id}")
            offset += varint_len2

            # Record body starts here
            # Parse header size varint
            header_size, varint_len3 = parse_varint(data, offset)
            print(f"  Header size: {header_size}")
            offset += varint_len3

            # Parse serial type codes
            serial_types = []
            header_offset = offset
            remaining_header = header_size - varint_len3
            while remaining_header > 0:
                st, st_len = parse_varint(data, header_offset)
                serial_types.append(st)
                header_offset += st_len
                remaining_header -= st_len

            print(f"  Serial types: {[f'{st:#04x}' for st in serial_types]}")

            # Decode values
            value_offset = header_offset
            values = []
            for st in serial_types:
                val, consumed = decode_value(data, value_offset, st)
                values.append(val)
                value_offset += consumed

            print(f"  Values: {values}")
            print()

            rows.append((row_id, values))

        except (IndexError, struct.error) as e:
            print(f"  ERROR parsing cell {i}: {e}")
            print(f"  Cell data: {data[cell_offset:].hex()}")
            print()
            break

    return rows

def main():
    with open('/app/trunc.db', 'rb') as f:
        data = f.read()

    print(f"File size: {len(data)} bytes")
    print()

    rows = parse_page(data)

    print(f"Recovered {len(rows)} rows")
    print()

    # Build output list
    output = []
    for row_id, values in rows:
        # The table seems to have columns: (id, word, value) or (word, value)
        # Based on the serial types: first is NULL, second is TEXT, third is value
        if len(values) >= 3:
            word = values[1]
            val = values[2]
        elif len(values) >= 2:
            word = values[0]
            val = values[1]
        else:
            continue

        if word is not None:
            output.append({"word": word, "value": val})

    with open('/app/recover.json', 'w') as f:
        json.dump(output, f, indent=2)

    print("Output written to /app/recover.json")
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

